parameters.jsCode:
const b = $json.body || {};
const d = b.data || {};
const key = d.key || {};

// بعض الرسائل بتيجي جوه غلاف (رسائل مؤقتة / عرض مرة واحدة)
let msg = d.message || {};
if (msg.ephemeralMessage && msg.ephemeralMessage.message) msg = msg.ephemeralMessage.message;
if (msg.viewOnceMessage && msg.viewOnceMessage.message) msg = msg.viewOnceMessage.message;
if (msg.documentWithCaptionMessage && msg.documentWithCaptionMessage.message) msg = msg.documentWithCaptionMessage.message;

const remoteJid = key.remoteJid || '';
const isGroup = remoteJid.endsWith('@g.us');
const sender = isGroup ? (key.participant || null) : remoteJid;

const text = msg.conversation
  || (msg.extendedTextMessage && msg.extendedTextMessage.text)
  || (msg.buttonsResponseMessage && (msg.buttonsResponseMessage.selectedDisplayText || msg.buttonsResponseMessage.selectedButtonId))
  || (msg.listResponseMessage && msg.listResponseMessage.title)
  || '';

let lat = null, lng = null, source = 'none';

// لوكيشن بالدبوس أو لوكيشن مباشر (Live)
const loc = msg.locationMessage || msg.liveLocationMessage;
if (loc) {
  lat = loc.degreesLatitude;
  lng = loc.degreesLongitude;
  source = msg.liveLocationMessage ? 'live' : 'pin';
}

const url = (text.match(/https?:\/\/\S+/) || [])[0] || null;
if (lat === null && url) {
  const m = url.match(/[?&](?:q|query|ll|destination)=(-?\d+\.\d+),(-?\d+\.\d+)/)
       || url.match(/@(-?\d+\.\d+),(-?\d+\.\d+)/)
       || url.match(/!3d(-?\d+\.\d+)!4d(-?\d+\.\d+)/);
  if (m) { lat = +m[1]; lng = +m[2]; source = 'link'; }
}

// رسالة تسجيل رقم الكابتن: "تسجيل 01012345678"
const regRe = new RegExp('^\\s*(\u062a\u0633\u062c\u064a\u0644|register)\\s*\\+?[\\d\u0660-\u0669\\s\\-]{9,}', 'i');
const isRegister = regRe.test(text);

return { json: {
  event: b.event || null,
  instanceName: b.instance || null,
  remoteJid,
  isGroup,
  sender,
  fromMe: !!key.fromMe,
  pushName: d.pushName || null,
  messageType: d.messageType || null,
  text,
  url,
  lat,
  lng,
  source,
  hasLocation: lat !== null,
  needsResolve: !!url && lat === null,
  isRegister
}};

const cust = $('Code in JavaScript').first().json;
const R = 6371;
const rad = d => d * Math.PI / 180;
const mapLink = `https://maps.google.com/?q=${cust.lat},${cust.lng}`;

const list = $input.all().map(i => i.json).map(c => {
  const dLat = rad(c.lat - cust.lat), dLng = rad(c.lng - cust.lng);
  const h = Math.sin(dLat/2)**2 +
            Math.cos(rad(cust.lat)) * Math.cos(rad(c.lat)) * Math.sin(dLng/2)**2;
  const km = 2 * R * Math.asin(Math.sqrt(h));
  return { name: c.name, km: +km.toFixed(2),
           minutes: Math.max(1, Math.round(km / 25 * 60)) };
}).sort((a, b) => a.km - b.km);

const n = list[0];
return [{ json: {
  remoteJid: cust.remoteJid,
  prompt: `The customer sent a location: ${mapLink}. ` +
    (n ? `Nearest captain: ${n.name}, ${n.km} km away, about ${n.minutes} minutes.`
       : 'No captains are available right now.')
}}];

