const prev = $('If1').first().json;
const subject = String($json.subject || '').toLowerCase();

let service = 'unknown';
if (/طرد|parcel/.test(subject)) service = 'parcel';
else if (/طعام|اكل|أكل|مطعم|food/.test(subject)) service = 'food';
else if (/راكب|ركاب|ride/.test(subject)) service = 'ride';

return { json: { ...prev, service } };

const DEFAULT_CC = '20'; // مصر. للأردن غيّره لـ '962'

const toEn = s => String(s)
  .replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d))
  .replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));

let raw = toEn($json.text).replace(/^\s*(تسجيل|register)/i, '');
let digits = raw.replace(/\D/g, '');

if (digits.startsWith('00')) digits = digits.slice(2);
else if (digits.startsWith('0')) digits = DEFAULT_CC + digits.slice(1);
else if (DEFAULT_CC === '20' && digits.length === 10 && digits.startsWith('1')) digits = DEFAULT_CC + digits;
else if (DEFAULT_CC === '962' && digits.length === 9 && digits.startsWith('7')) digits = DEFAULT_CC + digits;

return { json: { captain_id: $json.sender, phone: digits } };
